Her er et Python-skript som henter navn og stillingstittel fra offentlige registre:

```python
import requests

def fetch_data_from_public_register(email):
    # Eksempel: Hente informasjon fra Enhetsregisteret
    enhetsregister_url = f"https://www.enhetsregisteret.no/api/v1/businesses?epost={email}"
    headers = {
        "User-Agent": "DinAppNavn 1.0.0"
    }
    response = requests.get(enhetsregister_url, headers=headers)

    if response.status_code == 200:
        data = response.json()
        if "name" in data:
            return data["name"]
        else:
            return None

    # Eksempel: Hente informasjon fra Jobbnorge (eksempel-URL, juster etter behov)
    jobbnorge_url = f"https://api.jobbnorge.no/v1/person/{email}"
    response = requests.get(jobbnorge_url, headers=headers)

    if response.status_code == 200:
        data = response.json()
        if "name" in data:
            return data["name"]
        else:
            return None

    return None

def process_emails(email_list):
    personal_details = []
    for email in email_list['email']:
        data = fetch_data_from_public_register(email)
        if data:
            personal_details.append({
                "email": email,
                "name": data,
                "job_title": None  # Du må implementere funksjon for å hente stillingstittel
            })
    return personal_details

# Henter offentlig informasjon for e-poster i fila 'emails.csv'
personal_details = process_emails('emails.csv')
print(personal_details)
